  console.log('version:', pkg.version, 'exports:', pkg.exports);
});
"

node -e "
import('./node_modules/@re-cinq/eslint-plugin-re-lint/dist/index.mjs').then(m => {
  const plugin = m.default;
  for (const [name, rule] of Object.entries(plugin.rules)) {
    console.log(name, ':', rule.meta?.docs?.description || '');
  }
});
"

node -e "
